/**
 * DEF0777644: Test that triggers compile with only mandatory inputs.
 * Only mandatory: true fields are required, all others are optional.
 */
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

// Test 1: Record Created trigger - only 'table' has mandatory: true
// All other fields (run_on_extended, run_flow_in, condition, etc.) are optional
Flow(
    {
        $id: Now.ID['flow_trigger_mandatory_record_created'],
        name: 'DEF0777644: Record Created - Mandatory Only',
        description: 'Test that record created trigger compiles with only table input',
        runAs: 'system',
    },
    wfa.trigger(trigger.record.created, { $id: Now.ID['trig_mandatory_created'] }, { table: 'incident' }),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_mandatory_created'] },
            {
                log_level: 'info',
                log_message: 'Compiled with only mandatory table input',
            }
        )
    }
)

// Test 2: Daily trigger - only 'time' has mandatory: true
Flow(
    {
        $id: Now.ID['flow_trigger_mandatory_daily'],
        name: 'DEF0777644: Daily Trigger - Mandatory Only',
        description: 'Test that daily trigger compiles with only time input',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        { $id: Now.ID['trig_mandatory_daily'] },
        { time: Time({ hours: 9, minutes: 0, seconds: 0 }) }
    ),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_mandatory_daily'] },
            {
                log_level: 'info',
                log_message: 'Compiled with only mandatory time input',
            }
        )
    }
)

// Test 3: SLA Task trigger - no inputs defined, empty object is valid
Flow(
    {
        $id: Now.ID['flow_trigger_mandatory_sla'],
        name: 'DEF0777644: SLA Task - No Inputs',
        description: 'Test that sla task trigger compiles with empty inputs',
        runAs: 'system',
    },
    wfa.trigger(trigger.application.slaTask, { $id: Now.ID['trig_mandatory_sla'] }, {}),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_mandatory_sla'] },
            {
                log_level: 'info',
                log_message: 'Compiled with no inputs',
            }
        )
    }
)
